import{_ as e,o as a,c as s,ag as r}from"./chunks/framework.DNmTgtHf.js";const m=JSON.parse('{"title":"Part 10 — Messaging & Streaming","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_10_Messaging.md","filePath":"todo/study_plan/parts/Part_10_Messaging.md"}'),i={name:"todo/study_plan/parts/Part_10_Messaging.md"};function o(n,t,d,l,c,p){return a(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="part-10-—-messaging-streaming" tabindex="-1">Part 10 — Messaging &amp; Streaming <a class="header-anchor" href="#part-10-—-messaging-streaming" aria-label="Permalink to &quot;Part 10 — Messaging &amp; Streaming&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 6 (shared with Parts 11, 12). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_10-messaging-streaming-—-topic-inventory" tabindex="-1">10 Messaging &amp; Streaming — topic inventory <a class="header-anchor" href="#_10-messaging-streaming-—-topic-inventory" aria-label="Permalink to &quot;10 Messaging &amp; Streaming — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Delivery semantics — at-most-once, at-least-once, exactly-once (and why true EOS is rare)</td><td>🔴 💼 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>2</td><td>Ordering guarantees — global vs per-partition vs none</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Producer / consumer patterns, consumer groups</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Idempotency keys</td><td>🔴 💼 🎯</td><td>D</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 7 idempotency)</td></tr><tr><td>5</td><td>Dead-letter queues, retries, poison messages</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Spring Kafka — <code>@KafkaListener</code>, <code>ConcurrentMessageListenerContainer</code>, <code>DefaultErrorHandler</code>, dead-letter publishing recovery, batch listeners</td><td>🔴 💼</td><td>MP</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: @KafkaListener consuming from a topic, simulate exception, configure DefaultErrorHandler with 3-retry exponential backoff + DLT recoverer (30 min)</td></tr><tr><td>7</td><td>Kafka — partitions, replicas, ISR, offsets, compaction, exactly-once semantics</td><td>🟠 💼 🎯</td><td>D</td><td>3 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 Confluent Kafka docs &quot;Architecture&quot; page (~30 min) · 💻 Warm-up: produce + consume to a local Kafka topic with 3 partitions, observe consumer-group rebalance (30 min)</td></tr><tr><td>8</td><td>Retry topics pattern (Uber / Confluent-style) — <code>topic.retry.5m</code>, <code>topic.retry.30m</code>, <code>topic.dlt</code> chains; non-blocking retry without parking the consumer thread; Spring&#39;s <code>@RetryableTopic</code> annotation</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>SQS — standard vs FIFO, visibility timeout, long polling</td><td>🟠 💼 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>SNS — fan-out, filtering</td><td>🟠 💼 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Kinesis — shards, retention, consumer types</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>RabbitMQ — exchanges, queues, bindings, routing keys</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Event-driven architecture — events vs commands</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Outbox pattern (revisit)</td><td>🔴 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 4.3)</td></tr><tr><td>15</td><td>Change Data Capture (CDC) — Debezium, AWS DMS, MySQL binlog, Postgres logical replication</td><td>🟠 💼 🎯</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: run Debezium against local Postgres, observe a row INSERT propagate to a Kafka topic (30 min)</td></tr><tr><td>16</td><td>Transactional outbox + CDC — reliable event publishing without 2PC</td><td>🟠 💼 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>Choreography vs orchestration in event-driven architecture</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 4.3 Sagas)</td></tr><tr><td>18</td><td>Stream processing — Kafka Streams, Flink basics</td><td>🟡</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td>Schema registry, Avro / Protobuf for events; schema evolution rules</td><td>🟡</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~12.75 hrs</td><td>~1.16 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~34 hrs</td><td>~3.1 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~37 hrs</td><td>~3.36 wk</td><td></td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>Kafka — partitions, consumer groups, parallelism:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P[Producer] --&gt;|key-based partition routing| K[Kafka Topic&lt;br/&gt;3 partitions: P0, P1, P2]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    K --&gt; C1[Consumer Group A&lt;br/&gt;3 consumers, 1 per partition]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    K --&gt; C2[Consumer Group B&lt;br/&gt;2 consumers, P0+P1 → C2-a, P2 → C2-b]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note1[Within a partition: ordered&lt;br/&gt;Across partitions: no ordering&lt;br/&gt;One partition consumed by exactly one consumer per group]</span></span></code></pre></div><blockquote><p>Partition is the unit of ordering AND parallelism. Two consumer groups read independently. Within a group, partitions distribute among consumers (one partition can only be consumed by one consumer in the group at a time).</p></blockquote><p><strong>Transactional Outbox + CDC pattern:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant App as Application</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as Database (with outbox table)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant CDC as Debezium / DMS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant K as Kafka</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Cons as Consumer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;DB: BEGIN TX</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;DB: INSERT INTO orders</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;DB: INSERT INTO outbox (event)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;DB: COMMIT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over DB: Both writes atomic — same transaction</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CDC-&gt;&gt;DB: read WAL / binlog</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CDC-&gt;&gt;K: publish outbox row as event</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over CDC: At-least-once: CDC retries on failure</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    K-&gt;&gt;Cons: deliver event</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over App,Cons: Solves dual-write without 2PC</span></span></code></pre></div><blockquote><p>The Outbox table makes event publication a <em>consequence</em> of the DB commit, not a separate action that can fail independently. CDC reads the WAL after commit and publishes to Kafka.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Explain at-most-once, at-least-once, exactly-once. Why is &quot;exactly-once&quot; rare in practice? <ul><li><strong>Why asked:</strong> Senior-canonical messaging. At-most-once: send and forget, may lose. At-least-once: retries until ack, may duplicate. Exactly-once: theoretically achievable with idempotency + atomic commit (Kafka EOS within Kafka boundaries), but crossing system boundaries requires idempotent receivers. &quot;True exactly-once&quot; is asymptotic — design for at-least-once + idempotent processing.</li></ul></li><li><strong>Q:</strong> Why does Kafka guarantee ordering only per-partition, not globally? <ul><li><strong>Why asked:</strong> Architecture trade-off. Per-partition ordering allows parallel consumption (each partition consumed by one consumer in a group). Global ordering would force serial processing → no scale. If you need global ordering, use 1 partition (limits throughput) or order at the application layer using sequence numbers + reorder buffer.</li></ul></li><li><strong>Q:</strong> Walk through Outbox + CDC vs writing directly to Kafka inside a @Transactional method. <ul><li><strong>Why asked:</strong> Dual-write problem. Direct write: if DB commits and Kafka write fails, event is lost. Or vice versa. Outbox: write event to outbox table in same transaction → DB guarantees atomic commit. Separate process (CDC) reads outbox and publishes to Kafka with retries. Achieves at-least-once delivery without 2PC.</li></ul></li><li><strong>Q:</strong> Your consumer crashes after processing but before committing offset. What happens, and how do you handle it? <ul><li><strong>Why asked:</strong> Operational depth. Consumer restarts, reads from last-committed offset → re-processes messages. Requires idempotent message processing. Mitigations: (1) idempotency key on each message, (2) atomic process-and-commit pattern, (3) transactional outbox to track processed message IDs.</li></ul></li><li><strong>Q:</strong> SQS Standard vs FIFO — when does each fit? <ul><li><strong>Why asked:</strong> AWS-specific choice. Standard: at-least-once, no ordering, unlimited throughput, occasional duplicates. FIFO: exactly-once within a message group ID, strict ordering, but lower throughput (300 TPS unbatched, 3000 batched). FIFO is right when ordering matters (e.g., per-account event streams).</li></ul></li><li><strong>Q:</strong> Choreography vs orchestration in your KYC vendor flow — which would you pick? <ul><li><strong>Why asked:</strong> Architecture decision. Orchestration: KYC orchestrator decides the next step (current design). Easier to reason about, single point of complexity, easier to monitor. Choreography: each service reacts to events; looser coupling but harder to trace. KYC is naturally orchestration-friendly (single happy path with branches).</li></ul></li><li><strong>Q:</strong> What&#39;s a poison message and how do you handle it? <ul><li><strong>Why asked:</strong> Operational pattern. A message that consistently fails processing (malformed, references missing entity, hits a bug). Without handling, blocks the entire partition / queue. Fix: retry N times → move to DLQ → alert + manual inspection. Don&#39;t infinite-retry — wastes resources, blocks healthy messages behind it.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your consumer&#39;s <code>commitSync()</code> succeeds but processing failed. The message is now lost. What pattern would prevent this? <ul><li><strong>Gotcha:</strong> Process-then-commit ordering. Wrong: <code>consume → commit → process</code>. Right: <code>consume → process → commit</code>. Even better: process inside same transaction that commits offset, OR use idempotent processing so re-consumption is safe.</li></ul></li><li><strong>Q:</strong> Kafka exactly-once-semantics (EOS) is &quot;exactly-once&quot; — except when? <ul><li><strong>Gotcha:</strong> EOS is exactly-once <em>within Kafka boundaries</em> (producer → Kafka → consumer reading &amp; writing back to Kafka, all atomic with transactions). It&#39;s NOT exactly-once when the consumer&#39;s downstream effect is outside Kafka (DB write, external API call). That requires idempotency on the consumer side.</li></ul></li><li><strong>Q:</strong> Your team set up SNS → SQS fan-out. You added a Lambda consumer that calls a third-party API. Now you&#39;re seeing duplicate API calls. Why? <ul><li><strong>Gotcha:</strong> SNS → SQS is at-least-once. Lambda is also at-least-once invocation. Compounded, your consumer may run twice on the same message even without failures (Lambda timeout retries, SQS visibility timeout expiry, etc.). Always design downstream API calls to be idempotent (Idempotency-Key header).</li></ul></li><li><strong>Q:</strong> You configured Kafka with <code>acks=1</code>. Why might you still lose messages? <ul><li><strong>Gotcha:</strong> <code>acks=1</code> means leader acks before replicas replicate. If leader dies before replicating to ISR followers, messages are lost. Use <code>acks=all</code> (or <code>-1</code>) for durability — wait for all in-sync replicas. Trade-off: latency cost.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Delivery semantics deep dive + idempotency design</strong> (~3 hrs combined rows 1 + 4) — at-least-once is the default reality; design idempotent consumers. Tie to your KYC platform&#39;s webhook delivery pattern.</li><li><strong>Transactional Outbox + CDC end-to-end</strong> (~3 hrs combined rows 12 + 14) — solves the dual-write problem cleanly. Production-grade pattern; you may already use a variant on your KYC platform.</li><li><strong>Kafka partition strategy + consumer group rebalancing</strong> (~3 hrs row 6) — partition key choice, rebalance triggers, sticky vs range vs round-robin assignment strategies.</li><li><strong>DLQ + poison message handling pipeline</strong> (~2 hrs row 5) — retry budget, exponential backoff, DLQ routing, manual reinjection flow.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up messaging exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Kafka producer + consumer with partition key</strong> (~60 min) — local Kafka via Docker. Producer with a <code>key</code> parameter (e.g., user ID). 3 partitions. Verify all messages for one key land on the same partition. Then start a 2nd consumer in same group, observe rebalance.</li><li><strong>Implement idempotent consumer</strong> (~45 min) — consumer that reads from a queue + writes to a DB. Use unique message ID + dedup table (or <code>INSERT ... ON CONFLICT DO NOTHING</code>). Replay the same message 3 times — verify only one write.</li><li><strong>DLQ pipeline</strong> (~45 min) — SpringBoot or local Kafka consumer with retry decorator. After 3 failed attempts, move to a DLQ topic. Verify happy-path messages aren&#39;t affected by poison messages.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Transactional Outbox + Debezium walk-through</strong> (~90 min) — Postgres with an <code>outbox</code> table. Spring service writes business data + outbox row in same <code>@Transactional</code>. Debezium reads Postgres WAL and emits to Kafka. Observe end-to-end flow. Document the durability story.</li><li><strong>Composite ordering — global ordering with sequence numbers</strong> (~60 min) — Kafka topic with 4 partitions but you need global ordering. Add <code>sequence_number</code> to each message. Consumer reads from all 4 partitions, reorders by sequence number with a buffer. Document trade-offs (memory, latency).</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5 hrs</strong></td><td><strong>~0.45 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~1 hr 30 min for Part 10 across 3 in-table warm-ups (adds the Spring Kafka @KafkaListener + DefaultErrorHandler + DLT warm-up).</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. At-most-once vs at-least-once — fast definition.</strong> A. At-most-once: send and forget — never duplicates, may lose. At-least-once: retries until ack — never loses, may duplicate. Most systems are at-least-once + idempotent consumers (= effective exactly-once).</p><p><strong>Q. Why per-partition ordering instead of global?</strong> A. Per-partition allows parallel consumption. Global ordering forces single-consumer / single-partition serialization → no scale.</p><p><strong>Q. Outbox pattern — what problem does it solve?</strong> A. Dual-write: when you need to commit DB AND publish event atomically. Outbox: write event to DB table in same transaction; CDC reads outbox after commit, publishes reliably. No 2PC.</p><p><strong>Q. SQS Standard vs FIFO.</strong> A. Standard: unlimited throughput, may duplicate, no ordering. FIFO: exactly-once within message group ID, strict order, 300-3000 TPS limit. Pick FIFO when ordering matters.</p><p><strong>Q. What&#39;s a partition key in Kafka?</strong> A. The producer hashes the key to choose a partition. Same key → same partition → ordered consumption for that key. Common keys: user ID, session ID, entity ID. Skewed key distribution causes hot partition problems.</p><p><strong>Q. DLQ purpose?</strong> A. After N retries fail, route the poison message to a Dead Letter Queue. Frees up the main pipeline; surfaces problematic messages for manual triage. Always alert on DLQ depth.</p>`,35)])])}const u=e(i,[["render",o]]);export{m as __pageData,u as default};
